// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity 0.8.28;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {IKatanaV3Pool} from "../interfaces/IKatanaV3Pool.sol";

/// @notice Katana V3 arithmetic-mean tick consultation and quote helpers.
/// @dev Tick constants and ratio calculation are adapted from Uniswap V3 TickMath.
library KatanaTwap {
    error InvalidTwapWindow();
    error TickOutOfRange();
    error InvalidOracleLiquidity();

    int24 internal constant MAX_TICK = 887272;

    function consult(address pool, uint32 secondsAgo)
        internal
        view
        returns (int24 arithmeticMeanTick, uint128 harmonicMeanLiquidity)
    {
        if (secondsAgo == 0) revert InvalidTwapWindow();
        uint32[] memory secondsAgos = new uint32[](2);
        secondsAgos[0] = secondsAgo;
        secondsAgos[1] = 0;

        (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s) =
            IKatanaV3Pool(pool).observe(secondsAgos);
        int56 tickDelta = tickCumulatives[1] - tickCumulatives[0];
        uint160 liquidityDelta =
            secondsPerLiquidityCumulativeX128s[1] - secondsPerLiquidityCumulativeX128s[0];
        if (liquidityDelta == 0) revert InvalidOracleLiquidity();

        arithmeticMeanTick = int24(tickDelta / int56(uint56(secondsAgo)));
        if (tickDelta < 0 && tickDelta % int56(uint56(secondsAgo)) != 0) {
            arithmeticMeanTick--;
        }

        uint192 secondsAgoX160 = uint192(secondsAgo) * type(uint160).max;
        harmonicMeanLiquidity =
            uint128(secondsAgoX160 / (uint192(liquidityDelta) << 32));
        if (harmonicMeanLiquidity == 0) revert InvalidOracleLiquidity();
    }

    function getQuoteAtTick(
        int24 tick,
        uint128 baseAmount,
        address baseToken,
        address quoteToken
    ) internal pure returns (uint256 quoteAmount) {
        uint160 sqrtRatioX96 = getSqrtRatioAtTick(tick);
        if (sqrtRatioX96 <= type(uint128).max) {
            uint256 ratioX192 = uint256(sqrtRatioX96) * sqrtRatioX96;
            quoteAmount = baseToken < quoteToken
                ? Math.mulDiv(ratioX192, baseAmount, 1 << 192)
                : Math.mulDiv(1 << 192, baseAmount, ratioX192);
        } else {
            uint256 ratioX128 = Math.mulDiv(sqrtRatioX96, sqrtRatioX96, 1 << 64);
            quoteAmount = baseToken < quoteToken
                ? Math.mulDiv(ratioX128, baseAmount, 1 << 128)
                : Math.mulDiv(1 << 128, baseAmount, ratioX128);
        }
    }

    function getSqrtRatioAtTick(int24 tick) internal pure returns (uint160 sqrtPriceX96) {
        uint256 absTick = tick < 0 ? uint256(-int256(tick)) : uint256(int256(tick));
        if (absTick > uint256(uint24(MAX_TICK))) revert TickOutOfRange();

        unchecked {
            uint256 ratio = absTick & 0x1 != 0
                ? 0xfffcb933bd6fad37aa2d162d1a594001
                : 0x100000000000000000000000000000000;
            if (absTick & 0x2 != 0) ratio = (ratio * 0xfff97272373d413259a46990580e213a) >> 128;
            if (absTick & 0x4 != 0) ratio = (ratio * 0xfff2e50f5f656932ef12357cf3c7fdcc) >> 128;
            if (absTick & 0x8 != 0) ratio = (ratio * 0xffe5caca7e10e4e61c3624eaa0941cd0) >> 128;
            if (absTick & 0x10 != 0) ratio = (ratio * 0xffcb9843d60f6159c9db58835c926644) >> 128;
            if (absTick & 0x20 != 0) ratio = (ratio * 0xff973b41fa98c081472e6896dfb254c0) >> 128;
            if (absTick & 0x40 != 0) ratio = (ratio * 0xff2ea16466c96a3843ec78b326b52861) >> 128;
            if (absTick & 0x80 != 0) ratio = (ratio * 0xfe5dee046a99a2a811c461f1969c3053) >> 128;
            if (absTick & 0x100 != 0) ratio = (ratio * 0xfcbe86c7900a88aedcffc83b479aa3a4) >> 128;
            if (absTick & 0x200 != 0) ratio = (ratio * 0xf987a7253ac413176f2b074cf7815e54) >> 128;
            if (absTick & 0x400 != 0) ratio = (ratio * 0xf3392b0822b70005940c7a398e4b70f3) >> 128;
            if (absTick & 0x800 != 0) ratio = (ratio * 0xe7159475a2c29b7443b29c7fa6e889d9) >> 128;
            if (absTick & 0x1000 != 0) ratio = (ratio * 0xd097f3bdfd2022b8845ad8f792aa5825) >> 128;
            if (absTick & 0x2000 != 0) ratio = (ratio * 0xa9f746462d870fdf8a65dc1f90e061e5) >> 128;
            if (absTick & 0x4000 != 0) ratio = (ratio * 0x70d869a156d2a1b890bb3df62baf32f7) >> 128;
            if (absTick & 0x8000 != 0) ratio = (ratio * 0x31be135f97d08fd981231505542fcfa6) >> 128;
            if (absTick & 0x10000 != 0) ratio = (ratio * 0x9aa508b5b7a84e1c677de54f3e99bc9) >> 128;
            if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
            if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
            if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;
            if (tick > 0) ratio = type(uint256).max / ratio;
            sqrtPriceX96 =
                uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
        }
    }
}

contracts/MattBlackjackVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IERC20Burnable is IERC20 {
    function burn(uint256 amount) external;
}

contract MattBlackjackVault is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum Outcome { Loss, Surrender, Push, Win, Blackjack }

    struct Wager {
        address player;
        uint128 amount;
        uint64 openedAt;
        bool settled;
    }

    IERC20Burnable public immutable matt;
    address public immutable treasury;
    address public settlementOperator;
    uint256 public refundDelay;

    uint256 public lockedWagers;
    uint256 public reservedProfit;
    uint256 public totalClaimable;
    uint256 public totalBurned;
    uint256 public totalTreasuryFunded;
    uint256 public totalTreasuryWithdrawn;

    mapping(bytes32 => Wager) public wagers;
    mapping(address => uint256) public claimable;

    event SettlementOperatorUpdated(address indexed previousOperator, address indexed newOperator);
    event RefundDelayUpdated(uint256 previousDelay, uint256 newDelay);
    event BankrollFunded(address indexed treasury, uint256 amount);
    event BankrollWithdrawn(address indexed treasury, uint256 amount);
    event WagerOpened(bytes32 indexed wagerId, bytes32 indexed roundId, address indexed player, uint256 amount);
    event WagerSettled(bytes32 indexed wagerId, address indexed player, Outcome outcome, uint256 returnedPrincipal, uint256 profit, uint256 burned);
    event WagerRefunded(bytes32 indexed wagerId, address indexed player, uint256 amount);
    event PlayerWithdrawal(address indexed player, uint256 amount);

    error Unauthorized();
    error InvalidAddress();
    error InvalidAmount();
    error WagerAlreadyExists();
    error WagerNotOpen();
    error InsufficientBankroll();
    error RefundNotAvailable();

    constructor(address mattToken, address treasuryAddress, address operatorAddress) Ownable(treasuryAddress) {
        if (mattToken == address(0) || treasuryAddress == address(0) || operatorAddress == address(0)) revert InvalidAddress();
        matt = IERC20Burnable(mattToken);
        treasury = treasuryAddress;
        settlementOperator = operatorAddress;
        refundDelay = 2 hours;
        _pause();
    }

    modifier onlyTreasury() {
        if (msg.sender != treasury) revert Unauthorized();
        _;
    }

    modifier onlyOperator() {
        if (msg.sender != settlementOperator) revert Unauthorized();
        _;
    }

    function setSettlementOperator(address newOperator) external onlyOwner {
        if (newOperator == address(0)) revert InvalidAddress();
        address previous = settlementOperator;
        settlementOperator = newOperator;
        emit SettlementOperatorUpdated(previous, newOperator);
    }

    function setRefundDelay(uint256 newDelay) external onlyOwner {
        if (newDelay < 15 minutes || newDelay > 7 days) revert InvalidAmount();
        uint256 previous = refundDelay;
        refundDelay = newDelay;
        emit RefundDelayUpdated(previous, newDelay);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function fundBankroll(uint256 amount) external onlyTreasury nonReentrant {
        if (amount == 0) revert InvalidAmount();
        IERC20(address(matt)).safeTransferFrom(msg.sender, address(this), amount);
        totalTreasuryFunded += amount;
        emit BankrollFunded(msg.sender, amount);
    }

    function withdrawBankroll(uint256 amount) external onlyTreasury nonReentrant {
        if (amount == 0 || amount > unreservedBankroll()) revert InsufficientBankroll();
        totalTreasuryWithdrawn += amount;
        IERC20(address(matt)).safeTransfer(treasury, amount);
        emit BankrollWithdrawn(treasury, amount);
    }

    function openWager(bytes32 roundId, uint256 amount) external whenNotPaused nonReentrant returns (bytes32 wagerId) {
        if (roundId == bytes32(0) || amount == 0 || amount > type(uint128).max) revert InvalidAmount();
        wagerId = keccak256(abi.encodePacked(block.chainid, address(this), roundId, msg.sender));
        if (wagers[wagerId].player != address(0)) revert WagerAlreadyExists();

        uint256 maxProfit = blackjackProfit(amount);
        if (unreservedBankroll() < maxProfit) revert InsufficientBankroll();

        IERC20(address(matt)).safeTransferFrom(msg.sender, address(this), amount);
        wagers[wagerId] = Wager(msg.sender, uint128(amount), uint64(block.timestamp), false);
        lockedWagers += amount;
        reservedProfit += maxProfit;
        emit WagerOpened(wagerId, roundId, msg.sender, amount);
    }

    function settleWager(bytes32 wagerId, Outcome outcome) external onlyOperator whenNotPaused nonReentrant {
        Wager storage wager = wagers[wagerId];
        if (wager.player == address(0) || wager.settled) revert WagerNotOpen();

        wager.settled = true;
        uint256 amount = uint256(wager.amount);
        lockedWagers -= amount;
        reservedProfit -= blackjackProfit(amount);

        uint256 returnedPrincipal;
        uint256 profit;
        uint256 burned;

        if (outcome == Outcome.Loss) burned = amount;
        else if (outcome == Outcome.Surrender) {
            returnedPrincipal = amount / 2;
            burned = amount - returnedPrincipal;
        } else if (outcome == Outcome.Push) returnedPrincipal = amount;
        else if (outcome == Outcome.Win) {
            returnedPrincipal = amount;
            profit = amount;
        } else {
            returnedPrincipal = amount;
            profit = blackjackProfit(amount);
        }

        uint256 credit = returnedPrincipal + profit;
        if (credit != 0) {
            claimable[wager.player] += credit;
            totalClaimable += credit;
        }

        if (burned != 0) {
            matt.burn(burned);
            totalBurned += burned;
        }

        emit WagerSettled(wagerId, wager.player, outcome, returnedPrincipal, profit, burned);
    }

    function refundExpiredWager(bytes32 wagerId) external nonReentrant {
        Wager storage wager = wagers[wagerId];
        if (wager.player == address(0) || wager.settled) revert WagerNotOpen();
        if (msg.sender != wager.player && msg.sender != owner()) revert Unauthorized();
        if (!paused() && block.timestamp < uint256(wager.openedAt) + refundDelay) revert RefundNotAvailable();

        wager.settled = true;
        uint256 amount = uint256(wager.amount);
        lockedWagers -= amount;
        reservedProfit -= blackjackProfit(amount);
        claimable[wager.player] += amount;
        totalClaimable += amount;
        emit WagerRefunded(wagerId, wager.player, amount);
    }

    function withdraw() external nonReentrant {
        uint256 amount = claimable[msg.sender];
        if (amount == 0) revert InvalidAmount();
        claimable[msg.sender] = 0;
        totalClaimable -= amount;
        IERC20(address(matt)).safeTransfer(msg.sender, amount);
        emit PlayerWithdrawal(msg.sender, amount);
    }

    function blackjackProfit(uint256 wagerAmount) public pure returns (uint256) {
        return (wagerAmount * 3) / 2;
    }

    function protectedBalance() public view returns (uint256) {
        return lockedWagers + totalClaimable;
    }

    function availableBankroll() public view returns (uint256) {
        uint256 balance = matt.balanceOf(address(this));
        uint256 protectedTokens = protectedBalance();
        return balance > protectedTokens ? balance - protectedTokens : 0;
    }

    function unreservedBankroll() public view returns (uint256) {
        uint256 available = availableBankroll();
        return available > reservedProfit ? available - reservedProfit : 0;
    }

    function isSolvent() external view returns (bool) {
        return matt.balanceOf(address(this)) >= protectedBalance() + reservedProfit;
    }
}

contracts/MattCoinFlip.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title MATT Coin Flip
/// @notice A two-transaction commit/reveal coin flip using a future Ronin block hash.
/// @dev The player commits to a cryptographically random secret before the entropy block exists.
///      Revealing settles the bet immediately. Unrevealed bets expire to the immutable treasury.
contract MattCoinFlip is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum Choice {
        Heads,
        Tails
    }

    enum BetState {
        None,
        Pending,
        Won,
        Lost,
        Expired
    }

    struct Bet {
        address player;
        uint128 amount;
        uint64 entropyBlock;
        uint64 revealDeadlineBlock;
        Choice choice;
        BetState state;
        bytes32 commitment;
    }

    error ZeroAddress();
    error BetBelowMinimum(uint256 amount, uint256 minimum);
    error BetAboveMaximum(uint256 amount, uint256 maximum);
    error ActiveBetExists(uint256 betId);
    error InsufficientBankroll(uint256 available, uint256 required);
    error UnsupportedTokenBehavior();
    error BetNotPending(uint256 betId);
    error NotBetPlayer(address caller, address player);
    error EntropyBlockNotReady(uint256 currentBlock, uint256 requiredBlock);
    error RevealWindowClosed(uint256 currentBlock, uint256 deadlineBlock);
    error RevealWindowStillOpen(uint256 currentBlock, uint256 deadlineBlock);
    error InvalidSecret();
    error EntropyUnavailable();
    error WithdrawalExceedsAvailable(uint256 requested, uint256 available);
    error CannotRescueMatt();

    IERC20 public immutable matt;
    IERC20Permit public immutable mattPermit;
    address public immutable treasury;

    uint256 public constant MIN_BET = 1 ether;
    uint256 public constant MAX_BET = 1_000_000 ether;
    uint64 public constant ENTROPY_DELAY_BLOCKS = 1;
    uint64 public constant REVEAL_WINDOW_BLOCKS = 200;

    uint256 public nextBetId = 1;
    uint256 public reservedPayouts;

    mapping(uint256 betId => Bet bet) public bets;
    mapping(address player => uint256 betId) public activeBetOf;

    event BankrollFunded(address indexed funder, uint256 amount);
    event BankrollWithdrawn(address indexed recipient, uint256 amount);
    event BetPlaced(
        uint256 indexed betId,
        address indexed player,
        Choice choice,
        uint256 amount,
        uint256 entropyBlock,
        uint256 revealDeadlineBlock,
        bytes32 commitment
    );
    event BetSettled(
        uint256 indexed betId,
        address indexed player,
        Choice choice,
        Choice outcome,
        uint256 amount,
        uint256 payout,
        bool won,
        bytes32 entropyBlockHash,
        uint256 randomWord
    );
    event BetExpired(uint256 indexed betId, address indexed player, uint256 amount);

    constructor(address mattToken, address treasuryAddress, address initialOwner) Ownable(initialOwner) {
        if (mattToken == address(0) || treasuryAddress == address(0) || initialOwner == address(0)) {
            revert ZeroAddress();
        }

        matt = IERC20(mattToken);
        mattPermit = IERC20Permit(mattToken);
        treasury = treasuryAddress;
    }

    /// @notice Returns the commitment the website must submit with a bet.
    function commitmentFor(address player, Choice choice, uint256 amount, bytes32 secret)
        public
        view
        returns (bytes32)
    {
        return keccak256(abi.encode(secret, player, choice, amount, address(this), block.chainid));
    }

    /// @notice Places a bet using an existing ERC-20 allowance.
    function placeBet(Choice choice, uint256 amount, bytes32 commitment)
        external
        nonReentrant
        whenNotPaused
        returns (uint256 betId)
    {
        return _placeBet(msg.sender, choice, amount, commitment);
    }

    /// @notice Uses MATT's ERC-2612 permit and places the bet in one on-chain transaction.
    function placeBetWithPermit(
        Choice choice,
        uint256 amount,
        bytes32 commitment,
        uint256 permitDeadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external nonReentrant whenNotPaused returns (uint256 betId) {
        mattPermit.permit(msg.sender, address(this), amount, permitDeadline, v, r, s);
        return _placeBet(msg.sender, choice, amount, commitment);
    }

    function _placeBet(address player, Choice choice, uint256 amount, bytes32 commitment)
        internal
        returns (uint256 betId)
    {
        if (amount < MIN_BET) revert BetBelowMinimum(amount, MIN_BET);
        if (amount > MAX_BET) revert BetAboveMaximum(amount, MAX_BET);

        uint256 currentActiveBet = activeBetOf[player];
        if (currentActiveBet != 0) revert ActiveBetExists(currentActiveBet);

        uint256 balanceBefore = matt.balanceOf(address(this));
        matt.safeTransferFrom(player, address(this), amount);
        uint256 balanceAfter = matt.balanceOf(address(this));
        if (balanceAfter - balanceBefore != amount) revert UnsupportedTokenBehavior();

        uint256 payout = amount * 2;
        uint256 requiredBalance = reservedPayouts + payout;
        if (balanceAfter < requiredBalance) {
            revert InsufficientBankroll(balanceAfter - reservedPayouts, amount);
        }

        betId = nextBetId++;
        uint64 entropyBlock = uint64(block.number + ENTROPY_DELAY_BLOCKS);
        uint64 revealDeadlineBlock = entropyBlock + REVEAL_WINDOW_BLOCKS;

        bets[betId] = Bet({
            player: player,
            amount: uint128(amount),
            entropyBlock: entropyBlock,
            revealDeadlineBlock: revealDeadlineBlock,
            choice: choice,
            state: BetState.Pending,
            commitment: commitment
        });

        activeBetOf[player] = betId;
        reservedPayouts += payout;

        emit BetPlaced(
            betId,
            player,
            choice,
            amount,
            entropyBlock,
            revealDeadlineBlock,
            commitment
        );
    }

    /// @notice Reveals the precommitted secret and settles the bet immediately.
    function revealAndSettle(uint256 betId, bytes32 secret) external nonReentrant returns (bool won) {
        Bet storage bet = bets[betId];
        if (bet.state != BetState.Pending) revert BetNotPending(betId);
        if (msg.sender != bet.player) revert NotBetPlayer(msg.sender, bet.player);
        if (block.number <= bet.entropyBlock) {
            revert EntropyBlockNotReady(block.number, uint256(bet.entropyBlock) + 1);
        }
        if (block.number > bet.revealDeadlineBlock) {
            revert RevealWindowClosed(block.number, bet.revealDeadlineBlock);
        }

        if (commitmentFor(msg.sender, bet.choice, bet.amount, secret) != bet.commitment) {
            revert InvalidSecret();
        }

        bytes32 entropyBlockHash = blockhash(bet.entropyBlock);
        if (entropyBlockHash == bytes32(0)) revert EntropyUnavailable();

        uint256 randomWord = uint256(
            keccak256(abi.encodePacked(secret, entropyBlockHash, betId, address(this), block.chainid))
        );
        Choice outcome = Choice(uint8(randomWord & 1));
        won = outcome == bet.choice;

        uint256 amount = bet.amount;
        uint256 payout = amount * 2;

        bet.state = won ? BetState.Won : BetState.Lost;
        activeBetOf[bet.player] = 0;
        reservedPayouts -= payout;

        if (won) {
            matt.safeTransfer(bet.player, payout);
        } else {
            matt.safeTransfer(treasury, amount);
            payout = 0;
        }

        emit BetSettled(
            betId,
            bet.player,
            bet.choice,
            outcome,
            amount,
            payout,
            won,
            entropyBlockHash,
            randomWord
        );
    }

    /// @notice Sends an unrevealed bet to treasury after the reveal window closes.
    function expireBet(uint256 betId) external nonReentrant {
        Bet storage bet = bets[betId];
        if (bet.state != BetState.Pending) revert BetNotPending(betId);
        if (block.number <= bet.revealDeadlineBlock) {
            revert RevealWindowStillOpen(block.number, uint256(bet.revealDeadlineBlock) + 1);
        }

        uint256 amount = bet.amount;
        uint256 payout = amount * 2;

        bet.state = BetState.Expired;
        activeBetOf[bet.player] = 0;
        reservedPayouts -= payout;
        matt.safeTransfer(treasury, amount);

        emit BetExpired(betId, bet.player, amount);
    }

    /// @notice Funds the payout bankroll. Direct MATT transfers to the contract also increase bankroll.
    function fundBankroll(uint256 amount) external nonReentrant {
        uint256 balanceBefore = matt.balanceOf(address(this));
        matt.safeTransferFrom(msg.sender, address(this), amount);
        if (matt.balanceOf(address(this)) - balanceBefore != amount) revert UnsupportedTokenBehavior();
        emit BankrollFunded(msg.sender, amount);
    }

    /// @notice Amount the owner can withdraw without touching any pending-bet liability.
    function availableBankroll() public view returns (uint256) {
        uint256 balance = matt.balanceOf(address(this));
        return balance > reservedPayouts ? balance - reservedPayouts : 0;
    }

    /// @notice Maximum bet currently supportable by both the fixed cap and available bankroll.
    function maxAcceptableBet() external view returns (uint256) {
        uint256 available = availableBankroll();
        return available < MAX_BET ? available : MAX_BET;
    }

    function withdrawAvailableBankroll(address recipient, uint256 amount) external onlyOwner nonReentrant {
        if (recipient == address(0)) revert ZeroAddress();
        uint256 available = availableBankroll();
        if (amount > available) revert WithdrawalExceedsAvailable(amount, available);
        matt.safeTransfer(recipient, amount);
        emit BankrollWithdrawn(recipient, amount);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function rescueUnsupportedToken(address token, address recipient, uint256 amount)
        external
        onlyOwner
        nonReentrant
    {
        if (token == address(matt)) revert CannotRescueMatt();
        if (recipient == address(0)) revert ZeroAddress();
        IERC20(token).safeTransfer(recipient, amount);
    }
}

contracts/MattCoinFlipBurn.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IKatanaV3Pool} from "./interfaces/IKatanaV3Pool.sol";
import {IMattRewardVault} from "./interfaces/IMattRewardVault.sol";
import {KatanaTwap} from "./libraries/KatanaTwap.sol";

/// @title MATT BurnFlip Universal Wager Edition
/// @notice Accepts supported Ronin assets, forwards every wager to the treasury, and settles only in MATT.
/// @dev Uses a future-block commit/reveal outcome and a fixed-window Katana V3 TWAP recorded at bet placement.
contract MattCoinFlipBurn is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum Choice {
        Heads,
        Tails
    }

    enum BetState {
        None,
        Pending,
        Won,
        Lost,
        Expired
    }

    struct AssetConfig {
        address pool;
        uint128 minHarmonicLiquidity;
        bool supported;
    }

    struct Bet {
        address player;
        address asset;
        uint256 wagerAmount;
        uint256 mattEquivalent;
        uint256 payoutAmount;
        uint256 burnAmount;
        uint64 entropyBlock;
        uint64 revealDeadlineBlock;
        int24 meanTick;
        Choice choice;
        BetState state;
        bytes32 commitment;
    }

    error ZeroAddress();
    error UnsupportedAsset(address asset);
    error AssetAlreadySupported(address asset);
    error InvalidPool(address pool);
    error InvalidPoolFactory(address expected, address actual);
    error InvalidPoolPair(address token0, address token1);
    error PoolHasNoLiquidity(address pool);
    error OracleLiquidityTooLow(uint128 actual, uint128 minimum);
    error InvalidMinimumLiquidity();
    error InvalidWagerAmount();
    error WagerTooLarge(uint256 amount);
    error QuoteIsZero();
    error ActiveBetExists(uint256 betId);
    error InsufficientRewardVault(uint256 available, uint256 required);
    error RewardVaultPaused();
    error UnsupportedTokenBehavior();
    error TreasuryTransferFailed();
    error BetNotPending(uint256 betId);
    error NotBetPlayer(address caller, address player);
    error EntropyBlockNotReady(uint256 currentBlock, uint256 requiredBlock);
    error RevealWindowClosed(uint256 currentBlock, uint256 deadlineBlock);
    error RevealWindowStillOpen(uint256 currentBlock, uint256 deadlineBlock);
    error InvalidSecret();
    error EntropyUnavailable();
    error InvalidBasisPoints(uint256 value);
    error InvalidPayoutMultiplier(uint256 value);
    error OutstandingPayoutReservations(uint256 amount);

    address public constant NATIVE_RON = address(0);
    uint256 public constant BPS = 10_000;
    uint32 public constant TWAP_WINDOW = 30 minutes;
    uint16 public constant TARGET_OBSERVATION_CARDINALITY = 32;
    uint64 public constant ENTROPY_DELAY_BLOCKS = 1;
    uint64 public constant REVEAL_WINDOW_BLOCKS = 200;

    IERC20 public immutable matt;
    address public immutable wrappedRon;
    address public immutable katanaV3Factory;
    address payable public immutable treasury;

    IMattRewardVault public rewardVault;
    uint16 public burnBps = 7_500;
    uint32 public payoutMultiplierBps = 20_000;
    uint256 public nextBetId = 1;
    uint256 public reservedPayouts;
    uint256 public totalGames;
    uint256 public totalMattPaid;
    uint256 public totalMattBurned;

    mapping(address asset => AssetConfig config) public assetConfigs;
    mapping(uint256 betId => Bet bet) public bets;
    mapping(address player => uint256 betId) public activeBetOf;

    event SupportedAssetAdded(
        address indexed asset,
        address indexed pool,
        uint128 minHarmonicLiquidity
    );
    event SupportedAssetRemoved(address indexed asset);
    event V3PoolUpdated(
        address indexed asset,
        address indexed previousPool,
        address indexed newPool,
        uint128 minHarmonicLiquidity
    );
    event RewardVaultConfigured(address indexed previousVault, address indexed newVault);
    event BurnBpsConfigured(uint16 previousBps, uint16 newBps);
    event PayoutMultiplierConfigured(uint32 previousBps, uint32 newBps);
    event BetPlaced(
        uint256 indexed betId,
        address indexed player,
        address indexed asset,
        Choice choice,
        uint256 wagerAmount,
        uint256 mattEquivalent,
        uint256 payoutAmount,
        uint256 burnAmount,
        uint256 entropyBlock,
        uint256 revealDeadlineBlock,
        bytes32 commitment
    );
    event GamePlayed(
        uint256 indexed betId,
        address indexed player,
        address indexed asset,
        uint256 wagerAmount,
        uint256 mattEquivalent,
        Choice choice,
        Choice outcome,
        bool won,
        bool expired,
        uint256 payoutAmount,
        uint256 burnAmount
    );
    event WinnerPaid(uint256 indexed betId, address indexed player, uint256 amount);
    event MattBurned(uint256 indexed betId, address indexed player, uint256 amount, bool expired);
    event TreasuryDeposit(
        uint256 indexed betId,
        address indexed player,
        address indexed asset,
        uint256 amount
    );
    event PoolPriceUsed(
        uint256 indexed betId,
        address indexed asset,
        address indexed pool,
        uint32 twapWindow,
        int24 arithmeticMeanTick,
        uint128 harmonicMeanLiquidity,
        uint256 mattEquivalent
    );
    event BetExpired(uint256 indexed betId, address indexed player);
    event AccidentalTokenWithdrawn(address indexed token, uint256 amount);
    event AccidentalRonWithdrawn(uint256 amount);

    constructor(
        address mattToken,
        address wrappedRonToken,
        address v3Factory,
        address payable treasurySafe,
        address initialRewardVault,
        address initialOwner
    ) Ownable(initialOwner) {
        if (
            mattToken == address(0) || wrappedRonToken == address(0)
                || v3Factory == address(0) || treasurySafe == address(0)
                || initialRewardVault == address(0) || initialOwner == address(0)
        ) revert ZeroAddress();
        matt = IERC20(mattToken);
        wrappedRon = wrappedRonToken;
        katanaV3Factory = v3Factory;
        treasury = treasurySafe;
        rewardVault = IMattRewardVault(initialRewardVault);
        _pause();
    }

    function commitmentFor(
        address player,
        address asset,
        Choice choice,
        uint256 amount,
        bytes32 secret
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                secret,
                player,
                asset,
                choice,
                amount,
                address(this),
                block.chainid
            )
        );
    }

    function quoteMatt(address asset, uint256 amount)
        public
        view
        returns (
            uint256 mattEquivalent,
            int24 arithmeticMeanTick,
            uint128 harmonicMeanLiquidity,
            address pool
        )
    {
        AssetConfig memory config = assetConfigs[asset];
        if (!config.supported) revert UnsupportedAsset(asset);
        if (amount == 0) revert InvalidWagerAmount();
        if (amount > type(uint128).max) revert WagerTooLarge(amount);

        pool = config.pool;
        (arithmeticMeanTick, harmonicMeanLiquidity) =
            KatanaTwap.consult(pool, TWAP_WINDOW);
        if (harmonicMeanLiquidity < config.minHarmonicLiquidity) {
            revert OracleLiquidityTooLow(
                harmonicMeanLiquidity,
                config.minHarmonicLiquidity
            );
        }
        address oracleToken = asset == NATIVE_RON ? wrappedRon : asset;
        mattEquivalent = KatanaTwap.getQuoteAtTick(
            arithmeticMeanTick,
            uint128(amount),
            oracleToken,
            address(matt)
        );
        if (mattEquivalent == 0) revert QuoteIsZero();
    }

    function placeBet(
        address asset,
        Choice choice,
        uint256 amount,
        bytes32 commitment
    ) external nonReentrant whenNotPaused returns (uint256 betId) {
        if (asset == NATIVE_RON) revert InvalidWagerAmount();
        betId = _placeBet(msg.sender, asset, choice, amount, commitment);
        uint256 beforeBalance = IERC20(asset).balanceOf(treasury);
        IERC20(asset).safeTransferFrom(msg.sender, treasury, amount);
        if (IERC20(asset).balanceOf(treasury) - beforeBalance != amount) {
            revert UnsupportedTokenBehavior();
        }
        emit TreasuryDeposit(betId, msg.sender, asset, amount);
    }

    function placeRonBet(Choice choice, bytes32 commitment)
        external
        payable
        nonReentrant
        whenNotPaused
        returns (uint256 betId)
    {
        betId = _placeBet(
            msg.sender,
            NATIVE_RON,
            choice,
            msg.value,
            commitment
        );
        (bool sent,) = treasury.call{value: msg.value}("");
        if (!sent) revert TreasuryTransferFailed();
        emit TreasuryDeposit(betId, msg.sender, NATIVE_RON, msg.value);
    }

    function revealAndSettle(uint256 betId, bytes32 secret)
        external
        nonReentrant
        returns (bool won)
    {
        Bet storage bet = bets[betId];
        if (bet.state != BetState.Pending) revert BetNotPending(betId);
        if (msg.sender != bet.player) {
            revert NotBetPlayer(msg.sender, bet.player);
        }
        if (block.number <= bet.entropyBlock) {
            revert EntropyBlockNotReady(
                block.number,
                uint256(bet.entropyBlock) + 1
            );
        }
        if (block.number > bet.revealDeadlineBlock) {
            revert RevealWindowClosed(block.number, bet.revealDeadlineBlock);
        }
        if (
            commitmentFor(
                msg.sender,
                bet.asset,
                bet.choice,
                bet.wagerAmount,
                secret
            ) != bet.commitment
        ) revert InvalidSecret();

        bytes32 entropyHash = blockhash(bet.entropyBlock);
        if (entropyHash == bytes32(0)) revert EntropyUnavailable();
        uint256 randomWord = uint256(
            keccak256(
                abi.encodePacked(
                    secret,
                    entropyHash,
                    betId,
                    address(this),
                    block.chainid
                )
            )
        );
        Choice outcome = Choice(uint8(randomWord & 1));
        won = outcome == bet.choice;
        _clearReservation(bet);
        bet.state = won ? BetState.Won : BetState.Lost;

        if (won) {
            rewardVault.payWinner(bet.player, bet.payoutAmount);
            totalMattPaid += bet.payoutAmount;
            emit WinnerPaid(betId, bet.player, bet.payoutAmount);
        } else {
            rewardVault.burnMatt(bet.burnAmount);
            totalMattBurned += bet.burnAmount;
            emit MattBurned(betId, bet.player, bet.burnAmount, false);
        }

        totalGames++;
        emit GamePlayed(
            betId,
            bet.player,
            bet.asset,
            bet.wagerAmount,
            bet.mattEquivalent,
            bet.choice,
            outcome,
            won,
            false,
            bet.payoutAmount,
            bet.burnAmount
        );
    }

    function expireBet(uint256 betId) external nonReentrant {
        Bet storage bet = bets[betId];
        if (bet.state != BetState.Pending) revert BetNotPending(betId);
        if (block.number <= bet.revealDeadlineBlock) {
            revert RevealWindowStillOpen(
                block.number,
                uint256(bet.revealDeadlineBlock) + 1
            );
        }
        _clearReservation(bet);
        bet.state = BetState.Expired;
        rewardVault.burnMatt(bet.burnAmount);
        totalMattBurned += bet.burnAmount;
        totalGames++;

        emit MattBurned(betId, bet.player, bet.burnAmount, true);
        emit GamePlayed(
            betId,
            bet.player,
            bet.asset,
            bet.wagerAmount,
            bet.mattEquivalent,
            bet.choice,
            Choice(uint8(1) - uint8(bet.choice)),
            false,
            true,
            bet.payoutAmount,
            bet.burnAmount
        );
        emit BetExpired(betId, bet.player);
    }

    function addSupportedAsset(
        address asset,
        address pool,
        uint128 minHarmonicLiquidity
    ) external onlyOwner whenPaused {
        if (assetConfigs[asset].supported) {
            revert AssetAlreadySupported(asset);
        }
        _setAsset(asset, pool, minHarmonicLiquidity);
        emit SupportedAssetAdded(asset, pool, minHarmonicLiquidity);
    }

    function removeSupportedAsset(address asset) external onlyOwner whenPaused {
        if (!assetConfigs[asset].supported) revert UnsupportedAsset(asset);
        delete assetConfigs[asset];
        emit SupportedAssetRemoved(asset);
    }

    function updateV3Pool(
        address asset,
        address newPool,
        uint128 minHarmonicLiquidity
    ) external onlyOwner whenPaused {
        AssetConfig memory current = assetConfigs[asset];
        if (!current.supported) revert UnsupportedAsset(asset);
        _setAsset(asset, newPool, minHarmonicLiquidity);
        emit V3PoolUpdated(
            asset,
            current.pool,
            newPool,
            minHarmonicLiquidity
        );
    }

    function configureRewardVault(address newVault)
        external
        onlyOwner
        whenPaused
    {
        if (newVault == address(0)) revert ZeroAddress();
        if (reservedPayouts != 0) {
            revert OutstandingPayoutReservations(reservedPayouts);
        }
        address previous = address(rewardVault);
        rewardVault = IMattRewardVault(newVault);
        emit RewardVaultConfigured(previous, newVault);
    }

    function configureBurnBps(uint16 newBurnBps) external onlyOwner whenPaused {
        if (newBurnBps > BPS) revert InvalidBasisPoints(newBurnBps);
        uint16 previous = burnBps;
        burnBps = newBurnBps;
        emit BurnBpsConfigured(previous, newBurnBps);
    }

    function configurePayoutMultiplier(uint32 newMultiplierBps)
        external
        onlyOwner
        whenPaused
    {
        if (newMultiplierBps < BPS || newMultiplierBps > 100_000) {
            revert InvalidPayoutMultiplier(newMultiplierBps);
        }
        uint32 previous = payoutMultiplierBps;
        payoutMultiplierBps = newMultiplierBps;
        emit PayoutMultiplierConfigured(previous, newMultiplierBps);
    }

    function availableRewardBalance() public view returns (uint256) {
        uint256 balance = matt.balanceOf(address(rewardVault));
        return balance > reservedPayouts ? balance - reservedPayouts : 0;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        if (rewardVault.paused()) revert RewardVaultPaused();
        _unpause();
    }

    function emergencyWithdrawAccidentalToken(address token, uint256 amount)
        external
        onlyOwner
        whenPaused
        nonReentrant
    {
        if (token == address(0)) revert ZeroAddress();
        IERC20(token).safeTransfer(treasury, amount);
        emit AccidentalTokenWithdrawn(token, amount);
    }

    function emergencyWithdrawAccidentalRon(uint256 amount)
        external
        onlyOwner
        whenPaused
        nonReentrant
    {
        (bool sent,) = treasury.call{value: amount}("");
        if (!sent) revert TreasuryTransferFailed();
        emit AccidentalRonWithdrawn(amount);
    }

    function _placeBet(
        address player,
        address asset,
        Choice choice,
        uint256 amount,
        bytes32 commitment
    ) private returns (uint256 betId) {
        if (amount == 0) revert InvalidWagerAmount();
        uint256 current = activeBetOf[player];
        if (current != 0) revert ActiveBetExists(current);

        (
            uint256 mattEquivalent,
            int24 meanTick,
            uint128 harmonicLiquidity,
            address pool
        ) = quoteMatt(asset, amount);
        uint256 payoutAmount =
            mattEquivalent * payoutMultiplierBps / BPS;
        uint256 burnAmount = mattEquivalent * burnBps / BPS;
        uint256 required = reservedPayouts + payoutAmount;
        uint256 vaultBalance = matt.balanceOf(address(rewardVault));
        if (vaultBalance < required) {
            revert InsufficientRewardVault(vaultBalance, required);
        }
        if (rewardVault.paused()) revert RewardVaultPaused();

        betId = nextBetId++;
        uint64 entropyBlock = uint64(block.number + ENTROPY_DELAY_BLOCKS);
        uint64 deadline = entropyBlock + REVEAL_WINDOW_BLOCKS;
        bets[betId] = Bet({
            player: player,
            asset: asset,
            wagerAmount: amount,
            mattEquivalent: mattEquivalent,
            payoutAmount: payoutAmount,
            burnAmount: burnAmount,
            entropyBlock: entropyBlock,
            revealDeadlineBlock: deadline,
            meanTick: meanTick,
            choice: choice,
            state: BetState.Pending,
            commitment: commitment
        });
        activeBetOf[player] = betId;
        reservedPayouts = required;

        emit PoolPriceUsed(
            betId,
            asset,
            pool,
            TWAP_WINDOW,
            meanTick,
            harmonicLiquidity,
            mattEquivalent
        );
        emit BetPlaced(
            betId,
            player,
            asset,
            choice,
            amount,
            mattEquivalent,
            payoutAmount,
            burnAmount,
            entropyBlock,
            deadline,
            commitment
        );
    }

    function _clearReservation(Bet storage bet) private {
        activeBetOf[bet.player] = 0;
        reservedPayouts -= bet.payoutAmount;
    }

    function _setAsset(
        address asset,
        address pool,
        uint128 minHarmonicLiquidity
    ) private {
        if (pool == address(0) || pool.code.length == 0) {
            revert InvalidPool(pool);
        }
        if (minHarmonicLiquidity == 0) {
            revert InvalidMinimumLiquidity();
        }
        address oracleToken = asset == NATIVE_RON ? wrappedRon : asset;
        if (oracleToken == address(matt)) revert InvalidPool(pool);

        IKatanaV3Pool katanaPool = IKatanaV3Pool(pool);
        address actualFactory = katanaPool.factory();
        if (actualFactory != katanaV3Factory) {
            revert InvalidPoolFactory(katanaV3Factory, actualFactory);
        }
        address token0 = katanaPool.token0();
        address token1 = katanaPool.token1();
        bool validPair = (token0 == oracleToken && token1 == address(matt))
            || (token0 == address(matt) && token1 == oracleToken);
        if (!validPair) revert InvalidPoolPair(token0, token1);
        if (katanaPool.liquidity() == 0) revert PoolHasNoLiquidity(pool);

        katanaPool.increaseObservationCardinalityNext(
            TARGET_OBSERVATION_CARDINALITY
        );
        assetConfigs[asset] = AssetConfig({
            pool: pool,
            minHarmonicLiquidity: minHarmonicLiquidity,
            supported: true
        });
    }
}

contracts/MattCrashVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IERC20Burnable is IERC20 {
    function burn(uint256 amount) external;
}

contract MattCrashVault is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant BPS = 10_000;
    uint256 public constant HOUSE_EDGE_BPS = 100;
    uint256 private constant HASH_SPACE = 1 << 52;
    bytes32 private constant CRASH_DOMAIN = keccak256("MATT-CRASH-V2");

    struct Round {
        bytes32 commitment;
        uint64 bettingClosesAt;
        uint32 crashPointBps;
        bool revealed;
    }

    struct Wager {
        address player;
        bytes32 roundId;
        uint128 amount;
        uint64 openedAt;
        bool settled;
    }

    IERC20Burnable public immutable matt;
    address public immutable treasury;
    address public rewardsWallet;
    address public settlementOperator;

    uint256 public minWager;
    uint256 public maxWager;
    uint256 public maxCashoutBps;
    uint256 public refundDelay;
    uint256 public burnBps;
    uint256 public rewardsBps;

    uint256 public lockedWagers;
    uint256 public reservedProfit;
    uint256 public totalClaimable;
    uint256 public totalBurned;
    uint256 public totalRewardsSent;
    uint256 public totalTreasuryFunded;
    uint256 public totalTreasuryWithdrawn;

    mapping(bytes32 => Round) public rounds;
    mapping(bytes32 => Wager) public wagers;
    mapping(address => uint256) public claimable;

    event SettlementOperatorUpdated(address indexed previousOperator, address indexed newOperator);
    event RewardsWalletUpdated(address indexed previousWallet, address indexed newWallet);
    event LimitsUpdated(uint256 minWager, uint256 maxWager, uint256 maxCashoutBps);
    event LossAllocationUpdated(uint256 burnBps, uint256 rewardsBps);
    event RefundDelayUpdated(uint256 previousDelay, uint256 newDelay);
    event BankrollFunded(address indexed treasury, uint256 amount);
    event BankrollWithdrawn(address indexed treasury, uint256 amount);
    event RoundCommitted(bytes32 indexed roundId, bytes32 indexed commitment, uint256 bettingClosesAt);
    event RoundRevealed(bytes32 indexed roundId, bytes32 seed, uint256 crashPointBps);
    event WagerOpened(bytes32 indexed wagerId, bytes32 indexed roundId, address indexed player, uint256 amount);
    event WagerSettled(bytes32 indexed wagerId, address indexed player, uint256 cashoutBps, uint256 payout, uint256 burned, uint256 rewards);
    event WagerRefunded(bytes32 indexed wagerId, address indexed player, uint256 amount);
    event PlayerWithdrawal(address indexed player, uint256 amount);

    error Unauthorized();
    error InvalidAddress();
    error InvalidAmount();
    error InvalidRound();
    error RoundAlreadyExists();
    error RoundNotOpen();
    error RoundNotRevealed();
    error InvalidReveal();
    error WagerAlreadyExists();
    error WagerNotOpen();
    error InvalidCashout();
    error InsufficientBankroll();
    error RefundNotAvailable();

    constructor(
        address mattToken,
        address treasuryAddress,
        address operatorAddress,
        address rewardsAddress
    ) Ownable(treasuryAddress) {
        if (
            mattToken == address(0) ||
            treasuryAddress == address(0) ||
            operatorAddress == address(0) ||
            rewardsAddress == address(0)
        ) revert InvalidAddress();

        matt = IERC20Burnable(mattToken);
        treasury = treasuryAddress;
        settlementOperator = operatorAddress;
        rewardsWallet = rewardsAddress;

        minWager = 10_000 ether;
        maxWager = 10_000_000 ether;
        maxCashoutBps = 100 * BPS;
        refundDelay = 2 hours;
        burnBps = 1_000;
        rewardsBps = 500;
        _pause();
    }

    modifier onlyTreasury() {
        if (msg.sender != treasury) revert Unauthorized();
        _;
    }

    modifier onlyOperator() {
        if (msg.sender != settlementOperator) revert Unauthorized();
        _;
    }

    function setSettlementOperator(address newOperator) external onlyOwner {
        if (newOperator == address(0)) revert InvalidAddress();
        address previous = settlementOperator;
        settlementOperator = newOperator;
        emit SettlementOperatorUpdated(previous, newOperator);
    }

    function setRewardsWallet(address newWallet) external onlyOwner {
        if (newWallet == address(0)) revert InvalidAddress();
        address previous = rewardsWallet;
        rewardsWallet = newWallet;
        emit RewardsWalletUpdated(previous, newWallet);
    }

    function setLimits(uint256 newMinWager, uint256 newMaxWager, uint256 newMaxCashoutBps) external onlyOwner {
        if (
            newMinWager == 0 ||
            newMaxWager < newMinWager ||
            newMaxCashoutBps < BPS ||
            newMaxCashoutBps > 1_000 * BPS
        ) revert InvalidAmount();
        minWager = newMinWager;
        maxWager = newMaxWager;
        maxCashoutBps = newMaxCashoutBps;
        emit LimitsUpdated(newMinWager, newMaxWager, newMaxCashoutBps);
    }

    function setLossAllocation(uint256 newBurnBps, uint256 newRewardsBps) external onlyOwner {
        if (newBurnBps + newRewardsBps > 5_000) revert InvalidAmount();
        burnBps = newBurnBps;
        rewardsBps = newRewardsBps;
        emit LossAllocationUpdated(newBurnBps, newRewardsBps);
    }

    function setRefundDelay(uint256 newDelay) external onlyOwner {
        if (newDelay < 15 minutes || newDelay > 7 days) revert InvalidAmount();
        uint256 previous = refundDelay;
        refundDelay = newDelay;
        emit RefundDelayUpdated(previous, newDelay);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function fundBankroll(uint256 amount) external onlyTreasury nonReentrant {
        if (amount == 0) revert InvalidAmount();
        IERC20(address(matt)).safeTransferFrom(msg.sender, address(this), amount);
        totalTreasuryFunded += amount;
        emit BankrollFunded(msg.sender, amount);
    }

    function withdrawBankroll(uint256 amount) external onlyTreasury nonReentrant {
        if (amount == 0 || amount > unreservedBankroll()) revert InsufficientBankroll();
        totalTreasuryWithdrawn += amount;
        IERC20(address(matt)).safeTransfer(treasury, amount);
        emit BankrollWithdrawn(treasury, amount);
    }

    function commitRound(bytes32 roundId, bytes32 commitment, uint256 bettingClosesAt) external onlyOperator whenNotPaused {
        if (roundId == bytes32(0) || commitment == bytes32(0)) revert InvalidRound();
        if (rounds[roundId].commitment != bytes32(0)) revert RoundAlreadyExists();
        if (bettingClosesAt <= block.timestamp || bettingClosesAt > block.timestamp + 1 hours) revert InvalidRound();
        rounds[roundId] = Round(commitment, uint64(bettingClosesAt), 0, false);
        emit RoundCommitted(roundId, commitment, bettingClosesAt);
    }

    function revealRound(bytes32 roundId, bytes32 seed) external onlyOperator whenNotPaused returns (uint256 crashPointBps) {
        Round storage round = rounds[roundId];
        if (round.commitment == bytes32(0) || round.revealed) revert InvalidRound();
        if (block.timestamp < round.bettingClosesAt) revert RoundNotOpen();
        if (keccak256(abi.encodePacked(seed)) != round.commitment) revert InvalidReveal();

        crashPointBps = calculateCrashPointBps(seed, roundId);
        round.crashPointBps = uint32(crashPointBps);
        round.revealed = true;
        emit RoundRevealed(roundId, seed, crashPointBps);
    }

    function openWager(bytes32 roundId, uint256 amount) external whenNotPaused nonReentrant returns (bytes32 wagerId) {
        Round storage round = rounds[roundId];
        if (round.commitment == bytes32(0) || round.revealed || block.timestamp >= round.bettingClosesAt) revert RoundNotOpen();
        if (amount < minWager || amount > maxWager || amount > type(uint128).max) revert InvalidAmount();

        wagerId = keccak256(abi.encodePacked(block.chainid, address(this), roundId, msg.sender));
        if (wagers[wagerId].player != address(0)) revert WagerAlreadyExists();

        uint256 maxProfit = profitFor(amount, maxCashoutBps);
        if (unreservedBankroll() < maxProfit) revert InsufficientBankroll();

        IERC20(address(matt)).safeTransferFrom(msg.sender, address(this), amount);
        wagers[wagerId] = Wager(msg.sender, roundId, uint128(amount), uint64(block.timestamp), false);
        lockedWagers += amount;
        reservedProfit += maxProfit;
        emit WagerOpened(wagerId, roundId, msg.sender, amount);
    }

    function settleWager(bytes32 wagerId, uint256 cashoutBps) external onlyOperator whenNotPaused nonReentrant {
        _settleWager(wagerId, cashoutBps);
    }

    function settleWagers(bytes32[] calldata wagerIds, uint256[] calldata cashoutBpsValues) external onlyOperator whenNotPaused nonReentrant {
        if (wagerIds.length == 0 || wagerIds.length != cashoutBpsValues.length || wagerIds.length > 100) revert InvalidAmount();
        for (uint256 i = 0; i < wagerIds.length; ++i) {
            _settleWager(wagerIds[i], cashoutBpsValues[i]);
        }
    }

    function _settleWager(bytes32 wagerId, uint256 cashoutBps) internal {
        Wager storage wager = wagers[wagerId];
        if (wager.player == address(0) || wager.settled) revert WagerNotOpen();

        Round storage round = rounds[wager.roundId];
        if (!round.revealed) revert RoundNotRevealed();
        if (cashoutBps != 0 && (cashoutBps < BPS || cashoutBps >= round.crashPointBps || cashoutBps > maxCashoutBps)) {
            revert InvalidCashout();
        }

        wager.settled = true;
        uint256 amount = uint256(wager.amount);
        lockedWagers -= amount;
        reservedProfit -= profitFor(amount, maxCashoutBps);

        uint256 payout;
        uint256 burned;
        uint256 rewards;

        if (cashoutBps == 0) {
            burned = (amount * burnBps) / BPS;
            rewards = (amount * rewardsBps) / BPS;
            if (burned != 0) {
                matt.burn(burned);
                totalBurned += burned;
            }
            if (rewards != 0) {
                IERC20(address(matt)).safeTransfer(rewardsWallet, rewards);
                totalRewardsSent += rewards;
            }
        } else {
            payout = (amount * cashoutBps) / BPS;
            claimable[wager.player] += payout;
            totalClaimable += payout;
        }

        emit WagerSettled(wagerId, wager.player, cashoutBps, payout, burned, rewards);
    }

    function refundExpiredWager(bytes32 wagerId) external nonReentrant {
        Wager storage wager = wagers[wagerId];
        if (wager.player == address(0) || wager.settled) revert WagerNotOpen();
        if (msg.sender != wager.player && msg.sender != owner()) revert Unauthorized();

        Round storage round = rounds[wager.roundId];
        uint256 refundableAt = uint256(round.bettingClosesAt) + refundDelay;
        if (!paused() && block.timestamp < refundableAt) revert RefundNotAvailable();

        wager.settled = true;
        uint256 amount = uint256(wager.amount);
        lockedWagers -= amount;
        reservedProfit -= profitFor(amount, maxCashoutBps);
        claimable[wager.player] += amount;
        totalClaimable += amount;
        emit WagerRefunded(wagerId, wager.player, amount);
    }

    function withdraw() external nonReentrant {
        uint256 amount = claimable[msg.sender];
        if (amount == 0) revert InvalidAmount();
        claimable[msg.sender] = 0;
        totalClaimable -= amount;
        IERC20(address(matt)).safeTransfer(msg.sender, amount);
        emit PlayerWithdrawal(msg.sender, amount);
    }

    function calculateCrashPointBps(bytes32 seed, bytes32 roundId) public pure returns (uint256) {
        uint256 hashValue = uint256(keccak256(abi.encodePacked(seed, roundId, CRASH_DOMAIN)));
        uint256 h = hashValue >> 204;
        uint256 denominator = HASH_SPACE - h;
        uint256 result = ((BPS - HOUSE_EDGE_BPS) * HASH_SPACE) / denominator;
        if (result < BPS) return BPS;
        if (result > 1_000 * BPS) return 1_000 * BPS;
        return result;
    }

    function profitFor(uint256 wagerAmount, uint256 cashoutBps) public pure returns (uint256) {
        if (cashoutBps <= BPS) return 0;
        return (wagerAmount * (cashoutBps - BPS)) / BPS;
    }

    function protectedBalance() public view returns (uint256) {
        return lockedWagers + totalClaimable;
    }

    function availableBankroll() public view returns (uint256) {
        uint256 balance = matt.balanceOf(address(this));
        uint256 protectedTokens = protectedBalance();
        return balance > protectedTokens ? balance - protectedTokens : 0;
    }

    function unreservedBankroll() public view returns (uint256) {
        uint256 available = availableBankroll();
        return available > reservedProfit ? available - reservedProfit : 0;
    }

    function isSolvent() external view returns (bool) {
        return matt.balanceOf(address(this)) >= protectedBalance() + reservedProfit;
    }
}

